{
 "command": "git ls-files | head -100 && ls -a",
 "description": "List tracked files and top-level entries"
}

{
 "pattern": "**/{.gitlab-ci.yml,.circleci/*,Jenkinsfile,.travis.yml,azure-pipelines.yml,.github/**,Makefile,tox.ini,noxfile.py,docker-compose*.yml,pyproject.toml,requirements*.txt,package.json,.pre-commit-config.yaml}"
}

{
 "command": "for f in Makefile docker-compose.yml pyproject.toml services/notifier/pyproject.toml docs/testing.md docs/dev-setup.md .engramdb/memories/rerunning-ci-builds*.md .engramdb/memories/run-tests-with-make-test-fast*.md .engramdb/memories/release-by-tagging*.md .engramdb/memories/release-process-details*.md .engramdb/memories/running-the-notifier-s-tests*.md; do echo \"=== $f\"; cat \"$f\"; done; grep -rniE \"jenkins|circle|gitlab|buildkite|CI\\b|pipeline\" README.md docs scripts --include=* -l",
 "description": "Read build, test, and CI-related files"
}

{
 "command": "grep -niE -B2 -A2 \"ci\\b|jenkins|buildkite|pipeline|deploy|tag\" docs/runbook.md | head -60; grep -rn \"environ\\|getenv\" src scripts services --include=*.py | head -20; ls tests; grep -rn \"pytest.mark\" tests | head",
 "description": "Check runbook CI mentions, env vars, test markers"
}
